  [2937] = { "炼金术", "炼金术技能越高，能够学习的炼金术配方等级也越高。炼金术配方可从世界各地的训练师处学习，也可通过任务或从怪物身上获得。" },
  [2938] = { "锻造", "锻造技能越高，能够学习的锻造设计图等级也越高。锻造设计图可从世界各地的训练师处学习，也可通过任务或从怪物身上获得。" },
