  [2940] = { "附魔", "附魔技能越高，能够学习的附魔公式也越强大。附魔公式可从世界各地的训练师处学习，也可通过任务或从怪物身上获得。" },
  [2941] = { "工程学", "工程学技能越高，能够学习的工程学结构图等级也越高。结构图可从世界各地的训练师处学习，也可通过任务或从怪物身上获得。" },
  [2942] = { "急救", "急救技能越高，能够掌握的急救能力等级也越高。相关能力可从世界各地的训练师处学习，也可通过任务或从怪物身上获得。" },
  [2943] = { "钓鱼", "钓鱼技能越高，在世界各地水域中成功钓到鱼的几率也越高。如果你很难在某个区域钓到鱼，可前往等级较低的区域，或购买并使用鱼饵后再试。" },
  [2944] = { "草药学", "草药学技能越高，便能采集越难获取的草药。如果无法采集某种草药，可先在等级较低的区域采集较容易获取的草药，以提高技能。" },
  [2945] = { "制皮", "制皮技能越高，能够学习的制皮图样等级也越高。制皮图样可从世界各地的训练师处学习，也可通过任务或从怪物身上获得。" },
  [2946] = { "采矿", "采矿技能越高，便能开采越难采集的矿脉。如果无法开采某种矿脉，可先在等级较低的区域开采较容易采集的矿脉，以提高技能。" },
  [2947] = { "剥皮", "剥皮技能越高，便能对更高等级的怪物进行剥皮。技能超过100点后，将技能点数除以5，即可得出你能剥皮的怪物最高等级。" },
  [2948] = { "裁缝", "裁缝技能越高，能够学习的裁缝图样等级也越高。裁缝图样可从世界各地的训练师处学习，也可通过任务或从怪物身上获得。" },
  [2980] = { "天裔种族特长" },
  [2988] = { "药膏", "毒药技能越高，能制作的毒药就越强。你可以从毒药商人和行迹可疑的商贩那里购买材料，再将其调配成致命毒剂，令敌人腐烂、衰弱、枯萎。" },
