  [92] = { "吉尔吉斯半人马", "一群居住在凄凉之地南方的半人马，玛格拉姆半人马的仇敌。" },
  [93] = { "玛格拉姆半人马", "一群居住在凄凉之地东部的半人马，吉尔吉斯半人马的仇敌。" },
  [94] = { "玛洛迪" },
  [108] = { "塞拉摩" },
  [109] = { "剃刀沼泽野猪人" },
  [110] = { "钢鬃野猪人" },
  [128] = { "敌人" },
  [148] = { "小动物" },
  [168] = { "奈瑟加德商队" },
  [169] = { "热砂港" },
  [189] = { "联盟" },
  [209] = { "守望堡" },
  [229] = { "哀嚎洞穴" },
  [249] = { "异种蝎" },
  [269] = { "银月幸存者" },
  [270] = { "赞达拉部族", "这群居住在尤亚姆巴岛的巨魔正在努力招募全世界的勇士，希望他们能够帮助自己对抗祖尔格拉布中那个已经复活了的邪神哈卡，以及他手下的阿塔莱祭司们。" },
  [289] = { "锻造 - 武器锻造专精" },
  [309] = { "蝎子" },
  [310] = { "蝙蝠" },
  [311] = { "泰坦" },
  [329] = { "工头费苏勒" },
  [349] = { "拉文霍德", "这个由潜行者与刺客组成的行会只欢迎那些有着出色实力的人进入他们的领地。他们也是辛迪加的仇敌。" },
  [369] = { "加基森", "热砂集团的首府，诸多优秀地精技师、炼金师和商人的家乡。" },
  [409] = { "鹰身人" },
  [429] = { "火刃氏族" },
  [449] = { "暗影蛛丝偷猎者" },
  [469] = { "联盟" },
  [470] = { "棘齿城", "热砂集团的成员，这座城市给许多希望在贫瘠之地做生意的人提供了一个开放和中立的天堂。" },
  [471] = { "蛮锤部族", "尽管并非是联盟的一份子，但鹰巢山的矮人还是将联盟视为他们的朋友，并与部落保持着交战关系。" },
  [509] = { "阿拉索联军", "阿拉索联军正试图为暴风城夺回阿拉希盆地。" },
  [510] = { "污染者", "污染者试图为部落夺取阿拉希盆地的重要资源。" },
  [511] = { "巨人" },
  [529] = { "银色黎明", "一个致力于从亡灵天灾军团的威胁下拯救艾泽拉斯世界的组织。银色黎明的据点遍布东西瘟疫之地。" },
  [530] = { "暗矛巨魔", "一群被放逐的巨魔，加入了萨尔领导下的部落。他们现在将杜隆塔尔当作自己的新家，并与兽人盟友们一起生活在那里。" },
  [531] = { "青铜龙军团" },
  [532] = { "蓝龙军团" },
  [549] = { "制皮 - 部族制皮专精" },
  [550] = { "工程学 - 地精工程学专精" },
  [551] = { "工程学 - 侏儒工程学专精" },
  [569] = { "锻造 - 战锤锻造专精" },
  [570] = { "锻造 - 战斧锻造专精" },
  [571] = { "锻造 - 长剑锻造专精" },
  [572] = { "邪枝巨魔" },
  [573] = { "南海海盗" },
  [574] = { "凯尔达隆" },
  [575] = { "未堕落的熊怪" },
  [576] = { "木喉要塞", "作为最后一支尚未堕落的熊怪部族，木喉部族正致力于保留他们那种独特的精神修行之道，并试图终结其他熊怪部族的痛苦。" },
  [577] = { "永望镇", "热砂集团经营之下的一座贸易城市，坐落于冬泉谷的两条主要干道的交叉处。" },
  [589] = { "冬刃豹训练师", "这是一些专门在冬泉谷地区驯养冬泉霜刃豹的暗夜精灵。" },
  [609] = { "塞纳里奥议会", "塞纳里奥议会的德鲁伊是自然的守卫者，他们定居于宁静的月光林地。" },
  [629] = { "断矛巨魔" },
  [630] = { "暴掠龙训练师", "安戈洛环形山的暴掠龙凶悍无比，但仍有人学会了驯服它们。" },
  [649] = { "管理者埃克索图斯" },
  [729] = { "霜狼氏族", "霜狼氏族正在努力将雷矛探险队赶出奥特兰克山谷。" },
  [730] = { "雷矛卫队", "一群在奥特兰克山谷建立了永久居所的矮人，正与霜狼氏族的兽人激烈交战中。" },
  [749] = { "海达希亚水元素", "这些元素生物定居于艾萨拉的东部的一座小岛上，是拉格纳罗斯及其军团的死敌。" },
  [750] = { "萨弗隆火元素" },
  [769] = { "吉兹洛克的假人" },
  [771] = { "吉兹洛克" },
  [789] = { "莫洛加" },
  [809] = { "辛德拉", "一群居住在厄运之槌的精灵后裔，他们仍然具有着相当渊博的智慧与学识，并保守着一些伟大的秘密。" },
  [869] = { "加德纳尔" },
  [889] = { "战歌氏族", "战歌氏族是最具攻击性的兽人氏族，目前正与暗夜精灵的银翼哨兵部队在战歌峡谷激烈地交战中。" },
  [890] = { "银翼要塞", "灰谷地区坚定的守卫者，目前正与战歌氏族在战歌峡谷中激烈交战。" },
  [891] = { "联盟部队" },
  [892] = { "部落军队" },
  [893] = { "恶齿巨魔" },
  [909] = { "暗月马戏团", "一个向全世界展示着各类珍奇异宝的旅行马戏团。他们经常会访问艾尔文森林和莫高雷。" },
  [910] = { "诺兹多姆的子嗣", "青铜龙军团的后代，时间的守卫者，对凡人种族漠不关心。" },
  [912] = { "卡利姆多联军" },
  [915] = { "克苏恩的军队" },
  [916] = { "异种虫类" },
  [917] = { "铁炉堡军团" },
  [920] = { "红" },
  [921] = { "蓝" },
  [928] = { "天灾入侵者" },
  [1041] = { "疯狂" },
  [2505] = { "巨龙军团，多彩龙" },
  [2586] = { "艾泽拉斯贸易局", "艾泽拉斯贸易局（ACA）最初受命促进东部王国各地的贸易活动，现在负责维持联盟军队在世界各地的补给线。" },
  [2587] = { "杜隆塔尔补给后勤部", "部落活跃的补给网络促进了它在卡利姆多和其他地区的扩张。" },
  [2588] = { "S03 - 血色十字军伪装" },
  [2634] = { "鲜血之月", "天空一片殷红，嗜血的欲望压垮了你的感官！" },
  [2641] = { "翡翠卫士", "一伙仓促集结的德鲁伊，与联盟和部落携手扼制梦魇的进犯。" },
  [2646] = { "S03 - 50 - 塔纳利斯竞技场对手" },
  [2650] = { "S03 - 60 - 西瘟疫之地 - 法师符文铭刻" },
  [2660] = { "元素（熔火之心新增）" },
  [2661] = { "海达希亚（熔火之心新增）" },
  [2679] = { "白银之手骑士团", "一个由神圣战士所组成的修道会，立誓侍奉洛丹伦之王。" },
  [2686] = { "S03 - 天灾伪装" },
  [2687] = { "猎人任务首领（被驯服的野兽）" },
  [2719] = { "塞纳里奥斥候", "塞纳里奥斥候是一群年轻的自然爱好者，他们游走于艾泽拉斯的旷野之间，探索未知，也守护荒野。" },
  [2721] = { "S03 - 血色十字军", "纳克萨玛斯的NPC使用" },
  [2723] = { "S03 - 新阿瓦隆 - 血色十字军 - 伪装" },
  [2724] = { "S03 - 新阿瓦隆 - 血色十字军 - 巡逻队" },
  [2740] = { "肯瑞托", "肯瑞托云集世上最顶尖的法师，是统领达拉然这座魔法国度的最高法师议会。" },
  [2741] = { "肯瑞托 - 破碎" },
  [2745] = { "木喉要塞 - 不羁之魂 - 敌对" },
  [2746] = { "木喉要塞 - 不羁之魂 - 盟友" },
  [2747] = { "树皮地洞", "树皮部族是少数仍未堕落的熊怪之一。他们守护着先祖传下的精神传统，盼翼海加尔重归安宁。" },
  [2748] = { "申多雷" },
  [2749] = { "奥拉凯斯" },
  [2753] = { "死木熊怪" },
  [2754] = { "CTF - 旗帜 - 中立" },
  [2756] = { "海加尔臭鼬" },
  [2757] = { "泽风维和者" },
  [2758] = { "夜爪德鲁伊", "影风森林的德鲁伊行事隐秘，在泽风岛上独来独往，从不依附任何势力。" },
  [2759] = { "中立可被攻击" },
  [2760] = { "中立双方但部落可攻击" },
  [2761] = { "芬威克" },
  [2765] = { "海加尔守护者", "海加尔守护者出自塞纳里奥议会，肩负守护海加尔山与自然遗产的职责。凡愿一同抗击邪恶者，皆可加入他们的行列。" },
  [2768] = { "黑棘契约" },
  [2769] = { "吉尔吉斯流放者" },
  [2777] = { "野兽 - 掠食雄鹿" },
  [2778] = { "塑风者", "塑风者是泽风岛天裔族群中信奉萨满之道的精神领袖。他们敬奉元素，希望更深入地了解元素位面的本质，以此守护申多雷在天空之墙中的生活与传统。" },
  [2779] = { "高阶会", "高阶会成员皆为天裔，血脉源自埃雷萨拉斯的上层精灵魔导师。他们在天空之墙度过了一万年，如今正致力于寻回先辈遗留的古老奥术知识。" },
  [2782] = { "博尔德罗克氏族", "这些人因背叛虚假的“先知”而被暮光之锤流放，如今正试图走出一条属于自己的道路。" },
  [2785] = { "塞纳里奥议会（传说事件）" },
  [2786] = { "替换", "树皮部族是少数仍未堕落的熊怪之一。他们守护着先祖传下的精神传统，盼翼海加尔重归安宁。" },
  [2787] = { "大地之环", "大地之环由部落一方的萨满祭司与德鲁伊自发结成，在艾泽拉斯各地维系并滋养自然界的平衡。" },
  [2788] = { "灰烬统治" },
  [2789] = { "灰烬统治 - 术士伪装" },
  [2790] = { "CTF - 旗帜 - 中立" },
  [2794] = { "玩家，塑风者天裔" },
  [2795] = { "玩家，高阶会天裔" },
  [2798] = { "暗矛突袭者", "暗矛突袭者忠于巨魔一族，为争夺祖居之地——暗矛群岛的控制权，目前正与塞拉摩远征军交战。" },
  [2799] = { "塞拉摩远征军", "塞拉摩远征军一心效忠于塞拉摩城，为争夺所谓“暗矛群岛”的控制权，目前正与暗矛突袭者交战。" },
  [2800] = { "PvP等级点数" },
  [2801] = { "中立双方但联盟可攻击" },
  [2802] = { "传承进度" },
  [2813] = { "辛迪加伪装" },
  [2819] = { "守望者", "暗夜精灵社会中最强大的狱卒与执法者。他们日夜把守庞大的地下监牢网，不让任何威胁逃脱。" },
  [2826] = { "铁马兄弟会", "他们本是暴风城骑兵中的弃儿，却在东部海岸的未开之地另起炉灶，重建家园，结下新的盟约，也开辟了新的商路。" },
  [2827] = { "爆破引线港", "作为热砂集团的重要臂膀，这座港口聚集了纵横东部航线的海员，以及混迹暗巷的交易者。" },
};
